def load_best():
    if os.path.exists(BEST):
        with open(BEST) as f:
            return json.load(f)["params"]
    return None


def opt_label():
    b = load_best()
    return (f"Optimized design ({b.get('crew', 4)} crew, {b.get('o2_target', 1.0)*100:.0f} % O₂)"
            if b else None)


