# Lighting layouts: (lit surface factor, share of LED power inside the culture)
LAYOUTS = {
    "Panels lit from one side": (1.0, 0.0),
    "Panels lit from both sides": (2.0, 0.0),
    "LEDs inside + outside the tank": (2.5, 0.5),
    "LEDs inside only": (2.0, 1.0),
}


def apply_layout():
    lay = st.session_state["layout"]
    if lay in LAYOUTS:
        st.session_state["lit_area_factor"], st.session_state["internal_light_frac"] = LAYOUTS[lay]


def layout_name(factor, frac):
    for k, v in LAYOUTS.items():
        if abs(v[0] - factor) < 1e-6 and abs(v[1] - frac) < 1e-6:
            return k
    return "Custom"


def apply_preset():
    choice = st.session_state["preset"]
    base = asdict(Params())
    if choice == "Your current tank set":
        base.update(CURRENT)
    elif choice == opt_label():
        base.update(load_best())
    base["days"] = 250                       # default run length
    ints = {"crew", "days", "photoperiod_h", "urine_vol", "nit_vol", "ad1_vol", "ad2_vol", "rec_vol",
            "rods_per_tube"}
    for k in SLIDER_KEYS:
        v = base[k]
        if k in ints:
            v = int(round(v))
        elif isinstance(v, (int, float)) and not isinstance(v, bool):
            v = float(v)
        st.session_state[k] = v
    st.session_state["layout"] = layout_name(st.session_state["lit_area_factor"],
                                             st.session_state["internal_light_frac"])
    st.session_state["_tube_in"] = round(st.session_state["tube_d_m"] / 0.0254 * 2) / 2
    st.session_state["_rod_cm"] = round(st.session_state["rod_d_m"] * 100 * 2) / 2
    st.session_state["_gap_cm"] = round(st.session_state["rod_gap_m"] * 100 * 2) / 2


if "crew" not in st.session_state:
    st.session_state["preset"] = opt_label() or "Your current tank set"
    apply_preset()
# keep values of sliders that are hidden this run (Streamlit drops state of widgets it doesn't draw)
for _k in SLIDER_KEYS + ["_tube_in", "_rod_cm", "_gap_cm", "layout"]:
    if _k in st.session_state:
        st.session_state[_k] = st.session_state[_k]

