def tile(label, value, unit, note):
    return (f'<div class="wr-tile"><div class="wr-label">{label}</div>'
            f'<div class="wr-value">{value}<span class="wr-unit">{unit}</span></div>'
            f'<div class="wr-note">{note}</div></div>')


def check(status, name, value, limit, why="", fix=""):
    c, chip = {"pass": (GOOD, "✓ PASS"), "warn": (WARN, "! CHECK"), "fail": (BAD, "✕ FAIL")}[status]
    h = (f'<div class="wr-check" style="--c:{c}"><div class="wr-row">'
         f'<span class="wr-chip">{chip}</span><span class="wr-cname">{name}</span>'
         f'<span class="wr-cval">{value} <span class="wr-lim">· {limit}</span></span></div>')
    if why:
        h += f'<div class="wr-why">{why}</div>'
    if fix:
        h += f'<div class="wr-try"><b>Try:</b> {fix}</div>'
    return h + "</div>"


def signed(v, nd=1):
    """+1.2 / -0.4 / 0.0 (no '-0.0')."""
    v = 0.0 if abs(v) < 0.5 * 10 ** -nd else v
    return f"{v:+.{nd}f}" if v else f"{0:.{nd}f}"


